using System.Text;using System.Text.RegularExpressions;
namespace LSE.AutoCADElectrical.Librarian;
public static class IconMenuService {
 static readonly Regex PageHeader=new(@"^\*\*(\S+)\s*$"),LayoutLine=new(@"^D\d+W?$",RegexOptions.IgnoreCase),PageNumber=new(@"^M(\d+)$",RegexOptions.IgnoreCase),SlideRef=new(@"^[A-Za-z0-9_]+\(.*\)$");
 public static IconMenu Load(string path){if(!File.Exists(path))throw new FileNotFoundException("Icon menu file was not found.",path);byte[] b=File.ReadAllBytes(path);var m=new IconMenu{Path=path};Encoding e;int skip=0;
  if(b.Length>=3&&b[0]==0xEF&&b[1]==0xBB&&b[2]==0xBF){e=new UTF8Encoding(true);skip=3;}else if(b.Length>=2&&b[0]==0xFF&&b[1]==0xFE){e=new UnicodeEncoding(false,true);skip=2;}else if(b.Length>=2&&b[0]==0xFE&&b[1]==0xFF){e=new UnicodeEncoding(true,true);skip=2;}else{try{e=new UTF8Encoding(false,true);e.GetString(b);}catch{e=Encoding.Latin1;}}
  m.Encoding=e;string text=e.GetString(b,skip,b.Length-skip);m.NewLine=text.Contains("\r\n")?"\r\n":"\n";m.TrailingNewLine=text.EndsWith("\n");Parse(m,text);return m;}
 public static IconMenu Parse(string text){var m=new IconMenu{NewLine=text.Contains("\r\n")?"\r\n":"\n",TrailingNewLine=text.EndsWith("\n")};Parse(m,text);return m;}
 static void Parse(IconMenu m,string text){var lines=text.Split('\n').Select(l=>l.TrimEnd('\r')).ToList();if(m.TrailingNewLine&&lines.Count>0&&lines[^1].Length==0)lines.RemoveAt(lines.Count-1);IconMenuPage? page=null;bool titled=false;
  foreach(string line in lines){var h=PageHeader.Match(line);if(h.Success){page=new IconMenuPage{Id=h.Groups[1].Value};var n=PageNumber.Match(page.Id);if(n.Success)page.Number=int.Parse(n.Groups[1].Value);m.Pages.Add(page);titled=false;continue;}
   if(page is null){m.Header.Add(line);continue;}
   if(!titled){if(page.Layout is null&&page.Prelude.Count==0&&LayoutLine.IsMatch(line)){page.Layout=line;continue;}if(line.StartsWith(";")||line.Trim().Length==0){page.Prelude.Add(line);continue;}page.Title=line;titled=true;continue;}
   page.Entries.Add(ParseEntry(line));}}
 public static IconMenuEntry ParseEntry(string line){if(line.StartsWith(";"))return new IconMenuEntry{Raw=line};var p=line.Split('|');if(p.Length<3)return new IconMenuEntry{Raw=line};return new IconMenuEntry{Label=p[0],Image=p[1],Action=string.Join("|",p.Skip(2))};}
 public static string Render(IconMenu m){var sb=new StringBuilder();var x=new List<string>(m.Header);foreach(var p in m.Pages){x.Add("**"+p.Id);x.AddRange(p.Prelude);if(p.Layout is not null)x.Add(p.Layout);if(p.Title.Length>0||p.Entries.Count>0)x.Add(p.Title);foreach(var e in p.Entries)x.Add(e.ToString());}sb.Append(string.Join(m.NewLine,x));if(m.TrailingNewLine)sb.Append(m.NewLine);return sb.ToString();}
 public static byte[] Bytes(IconMenu m){var pre=m.Encoding.GetPreamble();var body=m.Encoding.GetBytes(Render(m));var b=new byte[pre.Length+body.Length];pre.CopyTo(b,0);body.CopyTo(b,pre.Length);return b;}
 public static void Save(IconMenu m,string? path=null){path??=m.Path;if(path.Length==0)throw new InvalidOperationException("The icon menu has no file path.");string t=path+".tmp";File.WriteAllBytes(t,Bytes(m));File.Move(t,path,true);m.Path=path;}
 public static int NextPageNumber(IconMenu m,int min=100){int n=m.Pages.Count==0?min-1:m.Pages.Max(p=>p.Number);return Math.Max(min,n+1);}
 public static IconMenuPage AddPage(IconMenu m,string title,IconMenuPage parent,string linkLabel,string linkImage){if(title.Trim().Length==0)throw new InvalidOperationException("A new icon menu page needs a title.");if(!m.Pages.Contains(parent))throw new InvalidOperationException("Parent page is not part of this menu.");var page=new IconMenuPage{Number=NextPageNumber(m),Title=title.Trim()};page.Id="M"+page.Number;m.Pages.Add(page);AddEntry(m,parent,linkLabel.Trim().Length>0?linkLabel.Trim():page.Title,linkImage,"$S="+page.Id);return page;}
 public static IconMenuEntry AddEntry(IconMenu m,IconMenuPage page,string label,string image,string action){if(label.Trim().Length==0)throw new InvalidOperationException("Icon menu label is required.");if(label.Contains('|')||image.Contains('|'))throw new InvalidOperationException("Icon menu label and image cannot contain '|'.");if(!m.Pages.Contains(page))throw new InvalidOperationException("Page "+page.Id+" is not part of this menu.");if(HasLabel(page,label))throw new InvalidOperationException($"Page {page.Id} ({page.Title}) already has an entry labelled \"{label}\". Choose another label.");var e=new IconMenuEntry{Label=label.Trim(),Image=image.Trim(),Action=action.Trim()};page.Entries.Add(e);return e;}
 public static bool HasLabel(IconMenuPage page,string label)=>page.Entries.Any(e=>e.IsEntry&&e.Label.Trim().Equals(label.Trim(),StringComparison.OrdinalIgnoreCase));
 public static HashSet<string> Reachable(IconMenu m,IEnumerable<string> roots){var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var queue=new Queue<string>(roots);while(queue.Count>0){string id=queue.Dequeue();if(!seen.Add(id))continue;var p=m.Page(id);if(p is null)continue;foreach(var e in p.Entries)if(e.IsEntry&&e.Submenu is {Length:>0} s&&!seen.Contains(s))queue.Enqueue(s);}return seen;}
 public static Dictionary<string,string> Breadcrumbs(IconMenu m,string root="M0"){var x=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);var queue=new Queue<(string Id,string Trail)>();var start=m.Page(root);if(start is not null){x[start.Id]=start.Title;queue.Enqueue((start.Id,start.Title));}
  while(queue.Count>0){var (id,trail)=queue.Dequeue();var p=m.Page(id);if(p is null)continue;foreach(var e in p.Entries){if(!e.IsEntry||e.Submenu is not {Length:>0} s||x.ContainsKey(s))continue;var child=m.Page(s);if(child is null)continue;string t=trail+" > "+(child.Title.Length>0?child.Title:e.Label);x[child.Id]=t;queue.Enqueue((child.Id,t));}}
  foreach(var p in m.Pages)if(!x.ContainsKey(p.Id))x[p.Id]="(unreachable) "+p.Title;return x;}
 public static List<(IconMenuPage Page,string Trail)> Tree(IconMenu m,IEnumerable<string> roots){var crumbs=Breadcrumbs(m);var ids=Reachable(m,roots);return m.Pages.Where(p=>ids.Contains(p.Id)).Select(p=>(p,crumbs.TryGetValue(p.Id,out var t)?t:p.Title)).ToList();}
 public static string? ResolveImage(IconMenu m,string image){string v=image.Trim();if(v.Length==0||SlideRef.IsMatch(v))return null;string ext=Path.GetExtension(v);if(!ext.Equals(".png",StringComparison.OrdinalIgnoreCase)&&!ext.Equals(".bmp",StringComparison.OrdinalIgnoreCase)&&!ext.Equals(".jpg",StringComparison.OrdinalIgnoreCase)&&!ext.Equals(".jpeg",StringComparison.OrdinalIgnoreCase)&&!ext.Equals(".gif",StringComparison.OrdinalIgnoreCase)&&!ext.Equals(".sld",StringComparison.OrdinalIgnoreCase))return null;if(Path.IsPathRooted(v))return v;string dir=Path.GetDirectoryName(m.Path)??"";return dir.Length==0?v:Path.Combine(dir,v);}
 public static MenuTarget ResolveAction(string action){string a=action.Trim();var t=new MenuTarget();if(a.Length==0){t.Kind="Other";return t;}if(a.StartsWith("$S=",StringComparison.OrdinalIgnoreCase)){t.Kind="Submenu";t.Path=a[3..].Trim();return t;}
  if(a.StartsWith("$C=",StringComparison.OrdinalIgnoreCase)){string rest=a[3..].Trim();int sp=rest.IndexOf(' ');t.Command=sp<0?rest:rest[..sp];string arg=sp<0?"":rest[(sp+1)..].Trim().Trim('"');t.Kind="Command";if(LooksLikePath(arg))t.Path=arg;return t;}
  if(a.StartsWith("$",StringComparison.Ordinal)){t.Kind="Other";return t;}if(LooksLikePath(a)){t.Kind="Path";t.Path=a.Trim('"');return t;}t.Kind="Block";t.BlockName=a;return t;}
 static bool LooksLikePath(string v)=>v.Contains('\\')||v.Contains('/')||v.EndsWith(".dwg",StringComparison.OrdinalIgnoreCase);
}
